1	use heck::ToKebabCase;
2	use proc_macro2::TokenStream;
3	use quote::{format_ident, quote};
4	use syn::parse::{Parse, ParseStream};
5	use syn::punctuated::Punctuated;
6	use syn::{Ident, Result, Token};
7	
8	use crate::util::{
9	    BlockWithReturn, Since, determine_name_and_title, documentation, foundations,
10	    has_attr, kw, oneliner, parse_attr, parse_flag, parse_key_value, parse_string,
11	    parse_string_array, validate_attrs,
12	};
